1	package release
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sync"
10		"syscall"
11	)
12	
13	const (
14		stateFileName = "ledger.json"
15		lockFileName  = "ledger.lock"
16		stateVersion  = 1
17	)
18	
19	// Store 是一个本地配方批次台账，数据保存在调用方指定的目录中。
20	// 不同目录互相独立；多个 Store 可以安全并发提交（进程内互斥、进程间文件锁）。
21	type Store struct {
22		dir      string
23		lockFile *os.File
24		mu       sync.Mutex
25		state    *persistedState
26	}
27	
28	// Open 打开（或首次使用）位于 dir 的台账。
29	// 目录不存在时会创建；目录中没有台账文件时得到空台账；
30	// 已有台账文件无法读取、解析，任一配方版本的任一物料每份克数不是正数，
31	// 任一批次绑定的配方版本未登记，
32	// 已保存投料的物料编号不属于该批次绑定的配方版本，
33	// 或已保存的投料数量非法（单条不是正数，或同一批次同一物料累计实投
34	// 超过 9223372036854775.807 克）时，返回 ErrCorruptData（可用 errors.Is
35	// 判断），不会当成空台账继续保存，也不会返回可继续使用的台账对象。
36	func Open(dir string) (*Store, error) {
37		if dir == "" {
38			return nil, errors.New("数据位置不能为空")
39		}
40		if err := os.MkdirAll(dir, 0o755); err != nil {
41			return nil, fmt.Errorf("创建数据位置 %q 失败: %w", dir, err)
42		}
43		info, err := os.Stat(dir)
44		if err != nil {
45			return nil, fmt.Errorf("读取数据位置 %q 失败: %w", dir, err)
46		}
47		if !info.IsDir() {
48			return nil, fmt.Errorf("数据位置 %q 不是目录", dir)
49		}
50	
51		lockPath := filepath.Join(dir, lockFileName)
52		lf, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
53		if err != nil {
54			return nil, fmt.Errorf("打开锁文件失败: %w", err)
55		}
56	
57		s := &Store{dir: dir, lockFile: lf}
58		if err := s.load(); err != nil {
59			lf.Close()
60			return nil, err
61		}
62		return s, nil
63	}
64	
65	// Close 释放台账占用的文件锁。
66	func (s *Store) Close() error {
67		s.mu.Lock()
68		defer s.mu.Unlock()
69		if s.lockFile == nil {
70			return nil
71		}
72		err := s.lockFile.Close()
73		s.lockFile = nil
74		return err
75	}
76	
77	func (s *Store) lockExclusive() error {
78		if s.lockFile == nil {
79			return errors.New("台账已关闭")
80		}
81		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_EX); err != nil {
82			return fmt.Errorf("锁定台账失败: %w", err)
83		}
84		return nil
85	}
86	
87	func (s *Store) lockShared() error {
88		if s.lockFile == nil {
89			return errors.New("台账已关闭")
90		}
91		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_SH); err != nil {
92			return fmt.Errorf("锁定台账失败: %w", err)
93		}
94		return nil
95	}
96	
97	func (s *Store) unlock() {
98		_ = syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_UN)
99	}
100	
101	func (s *Store) load() error {
102		data, err := os.ReadFile(filepath.Join(s.dir, stateFileName))
103		if err != nil {
104			if os.IsNotExist(err) {
105				s.state = &persistedState{Version: stateVersion, Requests: map[string]*requestRecord{}}
106				return nil
107			}
108			return fmt.Errorf("%w: 读取台账文件失败: %v", ErrCorruptData, err)
109		}
110		if len(data) == 0 {
111			s.state = &persistedState{Version: stateVersion, Requests: map[string]*requestRecord{}}
112			return nil
113		}
114		var st persistedState
115		if err := json.Unmarshal(data, &st); err != nil {
116			return fmt.Errorf("%w: 台账文件解析失败: %v", ErrCorruptData, err)
117		}
118		if st.Version != stateVersion {
119			return fmt.Errorf("%w: 台账版本 %d 不受支持", ErrCorruptData, st.Version)
120		}
121		if err := validateState(&st); err != nil {
122			return err
123		}
124		if st.Requests == nil {
125			st.Requests = map[string]*requestRecord{}
126		}
127		s.state = &st
128		return nil
129	}
130	
131	// validateState 检查台账的引用完整性与数量合法性：
132	//   - 每个配方版本的每种物料，每份克数必须是正数——与登记时的规则一致。
133	//     任一版本（包括尚未被任何批次使用的版本）的任一物料为零或负数，
134	//     整份台账即视为损坏：不能改成最小用量、取绝对值、删除问题物料
135	//     或改用其他版本后继续，其他配方完整或批次数量恰好吻合也不能放行。
136	//   - 每个批次记录的配方编号与版本号必须共同指向一个已登记的配方版本。
137	//     任一批次找不到对应版本，整份台账即视为损坏——不能改用同编号的其他版本，
138	//     也不能按名称或物料内容替换，即使其他批次仍然完整也不能放行本次读取。
139	//   - 每条已保存的投料数量必须是正数；同一批次内同一物料的累计实投
140	//     不得超过 maxGramsMilli（9223372036854775.807 克）。任一记录为零或
141	//     负数，或任一物料累计超限，整份台账即视为损坏——负数记录即使能被
142	//     正数抵消回范围内也不接受，超限也不能截断或忽略后继续。
143	//   - 每条已保存投料的物料编号必须属于该批次绑定的配方版本。归属以批次
144	//     实际绑定的版本为准：物料只出现在同编号的其他版本或其他配方中，
145	//     不能作为接受依据；也不能改选版本、补入物料或丢弃问题投料后继续。
146	func validateState(st *persistedState) error {
147		for _, r := range st.Recipes {
148			if r == nil {
149				return fmt.Errorf("%w: 台账中存在空的配方记录", ErrCorruptData)
150			}
151			for _, m := range r.Materials {
152				if m.GramsMilli <= 0 {
153					return fmt.Errorf("%w: 配方 %q 版本 %q 物料 %q 的每份克数不是正数",
154						ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
155				}
156			}
157		}
158		for _, b := range st.Batches {
159			if b == nil {
160				return fmt.Errorf("%w: 台账中存在空的批次记录", ErrCorruptData)
161			}
162			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
163			if r == nil {
164				return fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
165					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
166			}
167			if err := validateFeedings(b, r); err != nil {
168				return err
169			}
170		}
171		return nil
172	}
173	
174	// validateFeedings 检查一个批次内已保存投料的合法性与配方归属。
175	// 归属以批次绑定的配方版本 r 为准：每条投料的物料编号必须在 r 的物料
176	// 列表中，否则整份台账视为损坏。数量方面只判断数量本身是否合法，不判断
177	// 实投是否符合配方：无投料的物料累计为零属正常，不足或超过应投量也不
178	// 在此拒绝。
179	func validateFeedings(b *batchRecord, r *recipeRecord) error {
180		acc := newFeedingAccumulator()
181		for _, f := range b.Feedings {
182			belongs := false
183			for _, m := range r.Materials {
184				if m.MaterialNo == f.MaterialNo {
185					belongs = true
186					break
187				}
188			}
189			if !belongs {
190				return fmt.Errorf("%w: 批次 %q 的第 %d 条投料物料 %q 不属于其绑定的配方 %q 版本 %q",
191					ErrCorruptData, b.BatchNo, f.Seq, f.MaterialNo, b.RecipeNo, b.RecipeVersion)
192			}
193			if f.GramsMilli <= 0 {
194				return fmt.Errorf("%w: 批次 %q 物料 %q 的第 %d 条投料数量不是正数",
195					ErrCorruptData, b.BatchNo, f.MaterialNo, f.Seq)
196			}
197			if !acc.add(f.MaterialNo, f.GramsMilli) {
198				return fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出上限 %s 克",
199					ErrCorruptData, b.BatchNo, f.MaterialNo, maxGramsMilli)
200			}
201		}
202		return nil
203	}
204	
205	// persist 先写临时文件再原子改名，并 fsync 目录，保证已提交数据可恢复。
206	func (s *Store) persist(st *persistedState) error {
207		data, err := json.MarshalIndent(st, "", "  ")
208		if err != nil {
209			return err
210		}
211		tmpPath := filepath.Join(s.dir, stateFileName+".tmp")
212		f, err := os.OpenFile(tmpPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
213		if err != nil {
214			return err
215		}
216		if _, err := f.Write(data); err != nil {
217			f.Close()
218			return err
219		}
220		if err := f.Sync(); err != nil {
221			f.Close()
222			return err
223		}
224		if err := f.Close(); err != nil {
225			return err
226		}
227		if err := os.Rename(tmpPath, filepath.Join(s.dir, stateFileName)); err != nil {
228			return err
229		}
230		if d, err := os.Open(s.dir); err == nil {
231			_ = d.Sync()
232			_ = d.Close()
233		}
234		return nil
235	}
236	
237	func cloneState(st *persistedState) (*persistedState, error) {
238		data, err := json.Marshal(st)
239		if err != nil {
240			return nil, err
241		}
242		var out persistedState
243		if err := json.Unmarshal(data, &out); err != nil {
244			return nil, err
245		}
246		if out.Requests == nil {
247			out.Requests = map[string]*requestRecord{}
248		}
249		return &out, nil
250	}
251	
252	// write 是所有写入操作的统一入口：
253	//   - reqNo 为空直接报错；
254	//   - 同一 reqNo 且操作与内容完全相同，返回第一次成功的结果（幂等重放）；
255	//   - 同一 reqNo 用于其他操作或不同内容，返回 ErrRequestConflict；
256	//   - apply 在状态副本上执行，返回校验错误时不落盘、不占用请求编号；
257	//   - apply 成功后，状态与请求记录一起原子落盘，再切换到内存状态。
258	func (s *Store) write(reqNo, op string, payload any, apply func(*persistedState) (json.RawMessage, error), out any) error {
259		if reqNo == "" {
260			return errors.New("请求编号不能为空")
261		}
262		s.mu.Lock()
263		defer s.mu.Unlock()
264		if err := s.lockExclusive(); err != nil {
265			return err
266		}
267		defer s.unlock()
268	
269		// 跨进程场景下，其他进程可能已提交新数据；加锁后重新加载，
270		// 确保在最新状态上应用变更，避免用旧快照覆盖其他进程的写入。
271		if err := s.load(); err != nil {
272			return err
273		}
274	
275		payloadRaw, err := json.Marshal(payload)
276		if err != nil {
277			return err
278		}
279		payloadStr := string(payloadRaw)
280	
281		if req, ok := s.state.Requests[reqNo]; ok {
282			if req.Op != op || req.Payload != payloadStr {
283				return fmt.Errorf("%w: 请求编号 %q 已用于操作 %q，不能再用于操作 %q 或不同内容",
284					ErrRequestConflict, reqNo, req.Op, op)
285			}
286			if err := json.Unmarshal(req.Result, out); err != nil {
287				return fmt.Errorf("重放请求 %q 的结果失败: %w", reqNo, err)
288			}
289			return nil
290		}
291	
292		clone, err := cloneState(s.state)
293		if err != nil {
294			return err
295		}
296		result, err := apply(clone)
297		if err != nil {
298			return err
299		}
300		clone.Requests[reqNo] = &requestRecord{Op: op, Payload: payloadStr, Result: result}
301		if err := s.persist(clone); err != nil {
302			return fmt.Errorf("保存台账失败: %w", err)
303		}
304		s.state = clone
305		if err := json.Unmarshal(result, out); err != nil {
306			return fmt.Errorf("解析请求结果失败: %w", err)
307		}
308		return nil
309	}
310	
311	// read 在共享锁下读取当前状态。
312	func (s *Store) read(fn func(*persistedState) error) error {
313		s.mu.Lock()
314		defer s.mu.Unlock()
315		if err := s.lockShared(); err != nil {
316			return err
317		}
318		defer s.unlock()
319		if err := s.load(); err != nil {
320			return err
321		}
322		return fn(s.state)
323	}
324	
325	// 视图构造：每次都从记录全新构造，返回的切片与内部状态完全隔离。
326	
327	func buildRecipeView(r *recipeRecord) *RecipeView {
328		mats := make([]MaterialView, 0, len(r.Materials))
329		for _, m := range r.Materials {
330			mats = append(mats, MaterialView{MaterialNo: m.MaterialNo, Grams: m.GramsMilli.String()})
331		}
332		return &RecipeView{RecipeNo: r.RecipeNo, Version: r.Version, Name: r.Name, Materials: mats}
333	}
334	
335	func buildBatchView(b *batchRecord, r *recipeRecord) (*BatchView, error) {
336		v := &BatchView{
337			BatchNo:         b.BatchNo,
338			RecipeNo:        r.RecipeNo,
339			RecipeVersion:   r.Version,
340			RecipeName:      r.Name,
341			PlannedPortions: b.PlannedPortions,
342			Status:          b.Status,
343			Feedings:        make([]FeedingView, 0, len(b.Feedings)),
344			Materials:       make([]MaterialRequirement, 0, len(r.Materials)),
345		}
346	
347		for _, f := range b.Feedings {
348			v.Feedings = append(v.Feedings, FeedingView{
349				Seq:        f.Seq,
350				MaterialNo: f.MaterialNo,
351				Grams:      f.GramsMilli.String(),
352				Time:       f.Time,
353				Registrar:  f.Registrar,
354			})
355		}
356	
357		// 按物料累计实投量；台账在读取时已通过 validateFeedings 校验，
358		// 这里仍用同一套累计规则防一手整数回绕。
359		acc := newFeedingAccumulator()
360		for _, f := range b.Feedings {
361			if !acc.add(f.MaterialNo, f.GramsMilli) {
362				return nil, fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出可表示范围",
363					ErrCorruptData, b.BatchNo, f.MaterialNo)
364			}
365		}
366	
367		for _, m := range r.Materials {
368			required, err := multiplyPortions(m.GramsMilli, b.PlannedPortions)
369			if err != nil {
370				return nil, fmt.Errorf("批次 %q 数量核对失败: %w", b.BatchNo, err)
371			}
372			act := acc.total(m.MaterialNo)
373			v.Materials = append(v.Materials, MaterialRequirement{
374				MaterialNo:      m.MaterialNo,
375				RequiredGrams:   required.String(),
376				ActualGrams:     act.String(),
377				DifferenceGrams: (act - required).String(),
378			})
379		}
380		return v, nil
381	}
382	
383	func findRecipe(st *persistedState, recipeNo, version string) *recipeRecord {
384		for _, r := range st.Recipes {
385			if r.RecipeNo == recipeNo && r.Version == version {
386				return r
387			}
388		}
