	if err := json.Unmarshal(good, &broken); err != nil {
		t.Fatal(err)
	}
	broken.Recipes[0].Materials = append(broken.Recipes[0].Materials,
		materialRecord{MaterialNo: "M1", GramsMilli: 200000})
	badBytes := writeStateFile(t, dir, &broken)

