// 与读取已保存错误记录的 ErrCorruptData 不混用。
func TestRegisterRecipeDuplicateMaterialStaysInvalidInput(t *testing.T) {
	dir := t.TempDir()
	s, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
